message TransactionEvent {
  // Metadata about the event for tracing and versioning
  message Metadata {
    uint64 event_id = 1;             // Unique event identifier
    string source_id = 2;            // Originating service or node ID
    uint64 timestamp_unix_ms = 3;   // Event generation time in UNIX epoch milliseconds
    uint32 schema_version = 4;       // Schema version for compatibility
  }

  Metadata metadata = 1;

  // Core transaction data
