    string transaction_id = 1;        // Unique transaction ID
    string account_id = 2;            // Account related to transaction
    double amount = 3;                // Transaction amount (use double for precision)
    string currency = 4;              // ISO currency code (e.g. USD)
    int64 transaction_time_unix_ms = 5; // Transaction timestamp in UNIX epoch ms
    TransactionType type = 6;         // Type of transaction
    Status status = 7;                // Transaction status
