  TransactionData data = 2;

  // Upstream coordinator info to ensure consistent branching tree communication
  message UpstreamInfo {
    string coordinator_id = 1;        // Upstream coordinator node ID
    uint64 sequence_number = 2;       // Monotonically increasing sequence number
  }

  UpstreamInfo upstream = 3;

  // Reserved fields for future extension (field numbers 100-199)
  reserved 100 to 199;
}

